package feature.offer.data.modeldata class OfferResponse(    val id: String,    val title: String,    val description: String? = null,    val imageUrl: String? = null,    val discountPercentage: Double? = null,    val startDate: String? = null,    val endDate: String? = null)data class OfferListResponse(    val offers: List<OfferResponse>,    val page: Int,    val pageSize: Int,    val totalCount: Int)